-- PLAN NRW: Wissensseite + Pflegeplanung „Pflege beim intubierten Patienten“ (28.10.2026)
-- Fachlich freigegeben von P. Schenkelberger (Docs-Entwurf „Entwurf: Pflege beim intubierten Patienten“).
-- Im Supabase-SQL-Editor ausführen. Legt nur an, wenn der Slug noch nicht existiert.
insert into public.lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand, geprueft_von, geprueft_am)
select 'grundlagen', 'Intensivpflege', 'pflege-intubierter-patient', 'Pflege beim intubierten Patienten', $j${"definition": "Pflege von Menschen mit Endotrachealtubus, meist unter invasiver Beatmung und Sedierung. Ziel ist ein sicherer Atemweg ohne Komplikationen wie beatmungsassoziierte Pneumonie (VAP), Tubusdislokation, Druckschäden oder Delir.", "tabelle": {"kopf": ["Bereich", "Worauf du achtest", "Wie oft"], "zeilen": [["Tubuslage", "cm-Markierung an Zahnreihe/Mundwinkel mit Dokumentation vergleichen, seitengleiche Belüftung, Kapnografie-Kurve", "jede Schicht, nach Lagerung und Transport"], ["Fixierung", "fest, aber ohne Druck; Beißschutz bei Unruhe; orale Lage nach Standard umlagern", "jede Schicht"], ["Cuffdruck", "20–30 cmH₂O mit Cuffdruckmesser", "mind. 1× pro Schicht und nach Umlagerung"], ["Oberkörper", "30–45° hochlagern, wenn nichts dagegen spricht", "durchgehend"], ["Mund und Zähne", "Zähne putzen, Schleimhaut feucht halten, Lippen pflegen", "mehrmals täglich nach Hausstandard"], ["Absaugen", "nach Bedarf, nicht nach Uhrzeit; subglottisch, wenn der Tubus es kann", "bei Bedarf"], ["Augen", "Lidschluss prüfen, Hornhaut feucht halten und schützen", "jede Schicht"], ["Haut", "Druckstellen an Lippe, Mundwinkel und an den Ohren (Bänder)", "jede Schicht"], ["Bewusstsein, Schmerz, Delir", "RASS, BPS, CAM-ICU", "mind. alle 8 Stunden"]]}, "durchfuehrung": "VAP-Prophylaxe als Bündel: Händehygiene vor und nach jedem Kontakt, Oberkörper 30–45°, Cuffdruck 20–30 cmH₂O, subglottische Sekretabsaugung wenn vorhanden, Mundpflege mit Zähneputzen statt routinemäßiger Chlorhexidin-Spülung, täglich ärztlich prüfen lassen, ob Sedierung reduziert und extubiert werden kann, Kondenswasser nie Richtung Patient laufen lassen, Beatmungsschläuche nicht routinemäßig wechseln. Kommunikation: Intubierte können nicht sprechen, hören aber oft auch unter Sedierung mit – jede Maßnahme ankündigen, Ja-Nein-Fragen stellen, Buchstaben- oder Schreibtafel nutzen, Klingel in Reichweite, Brille und Hörgerät anlegen, Angehörige einbeziehen.", "klinische_relevanz": "Plötzliche Verschlechterung – an DOPES denken: Dislokation des Tubus, Obstruktion (Sekret, Abknicken, Beißen), Pneumothorax, Equipment (Gerät, Schläuche, Sauerstoff), Stacking (Air-Trapping). Sofort Hilfe holen; bei unklarer Ursache vom Respirator trennen und mit Beatmungsbeutel und 100 % Sauerstoff beatmen.", "komplikationen": "VAP, ungeplante Extubation, Tubusobstruktion, Druckschäden an Lippe und Trachea, stille Aspiration, Delir, Muskelabbau.", "pruefungswissen": "Cuffdruck 20–30 cmH₂O, Oberkörper 30–45°, Absaugen nach Bedarf, Tubuslage über die cm-Markierung kontrollieren und dokumentieren. Bei plötzlicher Verschlechterung an DOPES denken.", "merksatz": "Tubus fest, Cuff im Ziel, Kopf hoch, Mund sauber – und jede Maßnahme ansagen.", "haeufige_pruefungsfrage": "Welcher Cuffdruck wird beim Endotrachealtubus angestrebt?", "mcq": [{"frage": "Welcher Cuffdruck wird beim Endotrachealtubus angestrebt?", "optionen": ["20–30 cmH₂O", "5–10 cmH₂O", "40–50 cmH₂O", "So hoch wie möglich"], "richtig": 0}, {"frage": "Wofür steht das P in DOPES?", "optionen": ["Puls", "Pneumothorax", "Pupillen", "PEEP"], "richtig": 1}, {"frage": "Wann wird ein intubierter Patient abgesaugt?", "optionen": ["Stündlich", "Einmal pro Schicht", "Nach Bedarf", "Nur vor der Visite"], "richtig": 2}]}$j$::jsonb, true,
       'DGAI/DIVI-Empfehlungen; KRINKO Prävention nosokomialer beatmungsassoziierter Pneumonien', '2026-10-28', 'P. Schenkelberger', '2026-10-28'
where not exists (select 1 from public.lerninhalte where slug = 'pflege-intubierter-patient');

insert into public.lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand, geprueft_von, geprueft_am)
select 'grundlagen', 'Pflegeplanung', 'pflegeplanung-intubierter-patient', 'Pflegeplanung intubierter Patient', $j${"definition": "Musterpflegeplanung für einen intubierten, invasiv beatmeten Patienten auf der Intensivstation – mit drei typischen Pflegeproblemen nach PESR.", "symptome": "Endotrachealtubus, invasive Beatmung, Sedierung, eingeschränkte Kommunikation", "pflegeplanung": [{"problem": "Gefahr einer beatmungsassoziierten Pneumonie (VAP) infolge Endotrachealtubus, Sedierung und eingeschränktem Hustenstoß", "ressourcen": ["Kreislauf stabil", "toleriert Oberkörperhochlage"], "ziel": "keine Zeichen einer Pneumonie bis zur Extubation (Temperatur, Sekret und Oxygenierung unverändert)", "massnahmen": ["Oberkörper 30–45° hochlagern", "Cuffdruck mind. 1× pro Schicht messen, Ziel 20–30 cmH₂O", "Zähne putzen und Mundpflege nach Hausstandard", "Absaugen nach Bedarf, subglottisch absaugen, wenn vorhanden", "Kondenswasser vom Patienten weg ableiten", "Sedierung und Extubationsbereitschaft täglich mit dem Arzt besprechen"], "evaluation": "jede Schicht Temperatur, Sekret (Menge, Farbe, Geruch), Auskultation und Beatmungswerte dokumentieren"}, {"problem": "Beeinträchtigte verbale Kommunikation infolge Intubation, erkennbar an Unruhe, Gesten und Sprechversuchen", "ressourcen": ["wach (RASS 0 bis −1)", "kann nicken und mit Hilfe schreiben"], "ziel": "teilt innerhalb von 24 Stunden Schmerz, Durst und Lagerungswunsch über Ja-Nein-Zeichen oder Tafel mit", "massnahmen": ["Jede Maßnahme vorher ankündigen", "Ja-Nein-Zeichen vereinbaren und im Team weitergeben", "Buchstaben- oder Schreibtafel bereitlegen", "Klingel in Reichweite, Brille und Hörgerät anlegen", "Angehörige einbeziehen"], "evaluation": "jede Schicht prüfen, ob Bedürfnisse verstanden werden; Schmerz mit BPS erfassen"}, {"problem": "Gefahr eines Druckschadens an Lippe, Mundwinkel und Ohren infolge Tubus und Fixierband", "ressourcen": ["Haut und Schleimhaut aktuell intakt"], "ziel": "Haut und Schleimhaut bleiben bis zur Extubation intakt", "massnahmen": ["Fixierung jede Schicht auf Druck prüfen", "Orale Tubuslage nach Standard umlagern, dabei cm-Markierung kontrollieren", "Gefährdete Stellen polstern", "Lippen feucht halten und pflegen"], "evaluation": "jede Schicht Haut an Lippe, Mundwinkel und Ohren inspizieren und dokumentieren"}], "pruefungswissen": "Eine Pflegeplanung folgt dem Pflegeprozess: Pflegeproblem mit Ursache und Anzeichen (PESR-Schema), Ressourcen, ein messbares Pflegeziel (SMART), konkrete Maßnahmen und die Evaluation, ob das Ziel erreicht wurde. Die Beispiele hier sind Muster und müssen immer an den einzelnen Menschen angepasst werden.", "merksatz": "Problem – Ressource – Ziel – Maßnahme – Evaluation.", "haeufige_pruefungsfrage": "Welche Maßnahmen gehören zum VAP-Bündel?", "mcq": [{"frage": "Welcher Cuffdruck wird beim Endotrachealtubus angestrebt?", "optionen": ["20–30 cmH₂O", "5–10 cmH₂O", "40–50 cmH₂O", "So hoch wie möglich"], "richtig": 0}]}$j$::jsonb, true,
       'Pflegeprozess nach Fiechter/Meier; PESR-Schema', '2026-10-28', 'P. Schenkelberger', '2026-10-28'
where not exists (select 1 from public.lerninhalte where slug = 'pflegeplanung-intubierter-patient');

